const SCENES=[
 {title:T('Die Weinempfehlung','The wine recommendation','Le conseil en vin'),art:'wine',quote:T('„Ich kenne mich mit Wein nicht aus. Zum Fisch vielleicht etwas Weißes? Nicht zu sauer.“','“I don’t know much about wine. Perhaps something white with the fish? Not too acidic.”','« Je ne connais pas bien le vin. Peut-être un blanc avec le poisson ? Pas trop acide. »'),context:T('Der Fisch wird mit brauner Butter serviert. Du hast noch nicht nach dem Preisrahmen gefragt.','The fish comes with brown butter. You have not yet established the budget.','Le poisson est servi au beurre noisette. Vous n’avez pas encore abordé le budget.'),options:[T('Darf es eher rund und weich sein? Und in welchem Preisrahmen möchten Sie bleiben?','Would you prefer something round and mellow? And what price range would you be comfortable with?','Préférez-vous un vin rond et souple ? Et quel budget souhaitez-vous prévoir ?'),T('Dazu brauchen Sie einen mineralischen Wein mit hoher Säure.','You need a mineral wine with high acidity.','Il vous faut un vin minéral avec une acidité élevée.'),T('Ich bringe unsere teuerste Flasche Chardonnay.','I will bring our most expensive Chardonnay.','Je vous apporte notre Chardonnay le plus cher.')],answer:0,feedback:T('Du übersetzt den Wunsch in verständliche Eigenschaften und klärst den Rahmen. Anschließend kannst du einen passenden, eher runden Wein mit ausreichend Frische zur Butter vorschlagen.','You translate the request into clear characteristics and establish the budget. You can then suggest a rounder wine with enough freshness for the butter.','Vous reformulez l’envie avec des mots clairs et précisez le budget. Vous pourrez ensuite proposer un vin plutôt rond, assez frais pour accompagner le beurre.'),follow:T('Dein nächster Satz: „Ich habe zwei Möglichkeiten für Sie. Darf ich Ihnen den Unterschied kurz beschreiben?“','Your next sentence: “I have two options for you. May I briefly explain the difference?”','Votre prochaine phrase : « J’ai deux propositions pour vous. Puis-je vous en expliquer brièvement la différence ? »')},
 {title:T('Die Allergie','The allergy','L’allergie'),art:'oyster',quote:T('„Ich bin gegen Krebstiere allergisch. Kann ich die Fischsuppe essen?“','“I’m allergic to crustaceans. Can I have the fish soup?”','« Je suis allergique aux crustacés. Puis-je prendre la soupe de poisson ? »'),context:T('Die Karte nennt Fisch, aber nicht alle Bestandteile des Fonds.','The menu mentions fish but does not list every stock ingredient.','La carte mentionne le poisson, mais pas tous les ingrédients du fond.'),options:[T('Ja, Fisch ist kein Krebstier.','Yes, fish is not a crustacean.','Oui, un poisson n’est pas un crustacé.'),T('Ich prüfe mit der Küche den Fond, die Garnitur und mögliche Kreuzkontakte, bevor ich Ihnen etwas zusage.','I will check the stock, garnish and possible cross-contact with the kitchen before confirming.','Je vais vérifier le fond, la garniture et les risques de contact croisé avec la cuisine avant de vous répondre.'),T('Probieren Sie vorsichtig einen Löffel.','Try a small spoonful carefully.','Goûtez prudemment une cuillère.')],answer:1,feedback:T('Der Name eines Gerichts reicht nicht. In Fonds, Saucen und Garnituren können weitere Zutaten enthalten sein. Die Auskunft muss sich auf die aktuelle Rezeptur und den Arbeitsablauf stützen.','A dish’s name is not enough. Stocks, sauces and garnishes may contain other ingredients. Advice must be based on the current recipe and workflow.','Le nom du plat ne suffit pas. Fonds, sauces et garnitures peuvent contenir d’autres ingrédients. La réponse doit reposer sur la recette actuelle et les pratiques de préparation.'),follow:T('Informiere die Küche mit Tisch und Platz. Kehre mit einer bestätigten Auskunft zurück und kennzeichne eine vereinbarte Alternative eindeutig.','Inform the kitchen with table and seat details. Return with a verified answer and clearly identify any agreed alternative.','Transmettez la table et la place à la cuisine. Revenez avec une réponse confirmée et identifiez clairement l’alternative retenue.')},
 {title:T('Ohne Alkohol','Without alcohol','Sans alcool'),art:'herb',quote:T('„Ich möchte heute keinen Alkohol, aber trotzdem eine schöne Begleitung.“','“I don’t want alcohol tonight, but I would still love a thoughtful pairing.”','« Je ne souhaite pas d’alcool ce soir, mais j’aimerais tout de même un bel accord. »'),context:T('Zum Pilzgericht gibt es einen gekühlten Oolong und eine Fruchtkomposition.','The mushroom dish has a chilled oolong and a fruit-based pairing available.','Un oolong frais et une composition fruitée sont proposés avec les champignons.'),options:[T('Dann bleibt eigentlich nur Wasser.','Water is really the only option.','Il ne reste vraiment que de l’eau.'),T('Warum trinken Sie keinen Alkohol?','Why aren’t you drinking alcohol?','Pourquoi ne buvez-vous pas d’alcool ?'),T('Sehr gerne. Mögen Sie es eher frisch-fruchtig oder mit feinen Röstnoten? Soll es ausdrücklich 0,0 % sein?','Of course. Would you prefer fresh fruit or subtle roasted notes? Do you specifically require 0.0%?','Avec plaisir. Préférez-vous un accord frais et fruité ou de fines notes torréfiées ? Souhaitez-vous strictement 0,0 % ?')],answer:2,feedback:T('Du behandelst den Wunsch als eigenständige Genussentscheidung und klärst die konkrete Anforderung, ohne nach persönlichen Gründen zu fragen.','You treat the request as a considered dining choice and clarify the requirement without probing personal reasons.','Vous accueillez ce choix comme une véritable envie de dégustation et précisez le besoin sans demander de justification personnelle.'),follow:T('Beschreibe beide Optionen mit derselben Sorgfalt wie einen Wein. Prüfe vor einer 0,0-%-Zusage die Zutaten.','Describe both options with the same care as wine. Verify ingredients before promising 0.0%.','Présentez les deux options avec autant de soin qu’un vin. Vérifiez les ingrédients avant de garantir 0,0 %.')},
 {title:T('Die Wartezeit','The wait','L’attente'),art:'lemon',quote:T('„Wir warten schon länger auf den nächsten Gang und müssen um 21 Uhr gehen.“','“We’ve been waiting for the next course, and we need to leave at nine.”','« Nous attendons le prochain plat depuis un moment et devons partir à 21 heures. »'),context:T('Du kennst die aktuelle Wartezeit am Pass noch nicht.','You do not yet know the current wait at the pass.','Vous ne connaissez pas encore le délai au passe.'),options:[T('Es tut mir leid. Ich kläre sofort mit der Küche, wie wir Ihren Zeitrahmen einhalten können, und komme zu Ihnen zurück.','I am sorry. I will check with the kitchen straight away how we can work within your time, and come back to you.','Je suis désolé. Je vais voir immédiatement avec la cuisine comment respecter votre horaire et je reviens vers vous.'),T('In zwei Minuten kommt alles, versprochen.','Everything will be here in two minutes, I promise.','Tout arrive dans deux minutes, c’est promis.'),T('Ein Menü braucht eben Zeit.','A tasting menu takes time.','Un menu demande du temps.')],answer:0,feedback:T('Du nimmst die Zeitvorgabe ernst und versprichst nur den nächsten Schritt, den du selbst steuern kannst. Die Küche muss die tatsächliche Möglichkeit bestätigen.','You take the deadline seriously and promise only the next step you can control. The kitchen must confirm what is achievable.','Vous prenez l’horaire au sérieux et ne promettez que l’étape que vous maîtrisez. La cuisine doit confirmer ce qui est réalisable.'),follow:T('Vereinbare mit Küche und Serviceleiter einen realistischen Ablauf. Informiere den Gast offen über mögliche Anpassungen.','Agree a realistic plan with the kitchen and service manager. Tell the guest openly about possible adjustments.','Convenez d’un déroulement réaliste avec la cuisine et le responsable. Expliquez clairement les adaptations possibles.')}
];
let sceneAnswers={};
function labPage(){let d=DISHES[pairDish],v=d.variants[pairVariant],drinks=pairMode==='wine'?WINES:ZEROS;return `<div class="page-title"><h1>${txt(UI.labTitle)}</h1><p>${txt(UI.labIntro)}</p></div><section class="lab"><div><label for="dish-select">${txt(UI.dish)}</label><select id="dish-select">${DISHES.map((d,i)=>`<option value="${i}" ${i===pairDish?'selected':''}>${txt(d.name)}</option>`).join('')}</select><label for="variant-select">${txt(UI.variation)}</label><select id="variant-select">${d.variants.map((v,i)=>`<option value="${i}" ${i===pairVariant?'selected':''}>${txt(v.name)}</option>`).join('')}</select><div class="toggle">${['wine','zero'].map(m=>`<button data-mode="${m}" aria-pressed="${m===pairMode}">${txt(m==='wine'?UI.alcohol:UI.zero)}</button>`).join('')}</div><label for="drink-select">${txt(UI.drink)}</label><select id="drink-select">${drinks.map((w,i)=>`<option value="${i}" ${pairDrink===i?'selected':''}>${txt(w.name)}</option>`).join('')}</select><p class="hint">${txt(drinks[pairDrink].profile)}</p><button class="primary" id="compare">${txt(UI.compare)}${arrow}</button><div aria-live="polite">${pairRevealed?pairResult(v,drinks):''}</div></div><div class="dish-stage">${art(d.art)}<h2>${txt(d.name)}</h2><p>${txt(v.name)}</p><p>${txt(v.profile)}</p></div></section><section class="section aroma-section"><h2>${txt(UI.aromas)}</h2><p style="max-width:740px;margin-top:22px">${txt(UI.aromaIntro)}</p><div class="aroma-buttons">${AROMAS.map((a,i)=>`<button data-aroma="${i}" aria-pressed="${aromaIndex===i}">${txt(a[0])}</button>`).join('')}</div><p class="aroma-description">${txt(AROMAS[aromaIndex][1])}</p><p class="aroma-example">${txt(AROMAS[aromaIndex][2])}</p></section><section class="section"><div class="section-head"><h2>${txt(T('Jetzt wirklich probieren.','Now taste for yourself.','À présent, dégustez.'))}</h2><p>${txt(T('Die digitalen Kombinationen sind Lernbeispiele. Das konkrete Getränk, die Rezeptur und dein eigener Eindruck entscheiden.','The digital pairings are learning examples. The actual drink, recipe and your own perception determine the result.','Les accords numériques sont des exemples pédagogiques. La boisson réelle, la recette et votre perception déterminent le résultat.'))}</p></div><p class="reading">${txt(T('Vergleiche einen kleinen Bissen zuerst mit Wasser, dann mit einer gewählten Begleitung. Rieche, probiere und atme aus. Was wird deutlicher, was tritt zurück? Notiere eine Beobachtung statt einer Punktzahl. Verwende ausschließlich verträgliche Zutaten; eine Verkostung mit Alkohol ist freiwillig.','Compare a small bite first with water, then with your chosen drink. Smell, taste and breathe out. What becomes more noticeable, and what recedes? Record an observation rather than a score. Use only safe ingredients for you; tasting alcohol is optional.','Comparez une bouchée avec de l’eau, puis avec la boisson choisie. Sentez, goûtez et expirez. Qu’est-ce qui se révèle ou s’efface ? Notez une observation plutôt qu’une note chiffrée. Utilisez uniquement des ingrédients que vous tolérez ; déguster de l’alcool reste facultatif.'))}</p><div class="actions"><a class="primary" href="#notes">${txt(UI.noteLabel)}${arrow}</a><a href="#lesson/pairing">${txt(T('Die Grundlagen vertiefen','Explore the principles','Approfondir les principes'))}</a></div></section>`}
function pairResult(v,drinks){let recommended=v[pairMode],match=pairDrink===recommended,heavy=drinks[pairDrink].weight>v.weight;return `<div class="pair-result"><h3>${txt(match?T('Ein stimmiger Ausgangspunkt.','A harmonious starting point.','Un point de départ harmonieux.'):T('Vergleiche die Balance.','Compare the balance.','Comparez l’équilibre.'))}</h3><p>${txt(match?v.why:heavy?T('Diese Begleitung bringt mehr Gewicht mit als das Gericht. Prüfe, ob sie Textur und feine Aromen überdeckt. Das ist ein Anlass zum Vergleichen, kein pauschales Verbot.','This drink has more weight than the dish. Check whether it masks texture and delicate aromas. This is a reason to compare, not a blanket rule.','Cette boisson a plus de poids que le plat. Vérifiez si elle masque les textures et les arômes délicats. C’est une invitation à comparer, pas une interdiction.'):T('Diese Variante kann funktionieren, setzt aber andere Akzente. Vergleiche vor allem Süße, Säure und Intensität mit der vorgeschlagenen Begleitung.','This option may work, but changes the emphasis. Compare sweetness, acidity and intensity with the suggested pairing.','Cette option peut fonctionner, mais modifie les accents. Comparez surtout douceur, acidité et intensité avec l’accord proposé.'))}</p>${match?'':`<p><strong>${txt(T('Zum Vergleich','For comparison','À comparer'))}: ${txt(drinks[recommended].name)}</strong></p><p>${txt(v.why)}</p>`}</div>`}
function tablePage(){let s=SCENES[currentScene],chosen=sceneAnswers[currentScene];return `<div class="page-title"><h1>${txt(UI.tableTitle)}</h1><p>${txt(UI.tableIntro)}</p></div><div class="scenario-tabs">${SCENES.map((s,i)=>`<button data-scene="${i}" aria-pressed="${i===currentScene}">${i+1}. ${txt(s.title)}</button>`).join('')}</div><section class="scene">${art(s.art)}<div><blockquote>${txt(s.quote)}</blockquote><p>${txt(s.context)}</p></div></section><section class="exercise"><div class="exercise-inner"><h2>${txt(UI.decide)}</h2><div class="options">${s.options.map((o,i)=>`<button class="option ${chosen===i?'selected':''}" data-scene-answer="${i}" aria-pressed="${chosen===i}"><span>${String.fromCharCode(65+i)}</span><span>${txt(o)}</span></button>`).join('')}</div><div class="feedback" aria-live="polite">${chosen!==undefined?`<strong>${txt(chosen===s.answer?UI.correct:UI.retry)}</strong><p>${txt(s.feedbackByChoice?.[chosen] || s.feedback)}</p>${chosen===s.answer?`<p>${txt(s.follow)}</p>`:""}`:''}</div>${chosen===s.answer?`<div class="actions"><button class="text-button" id="next-scene">${txt(currentScene<SCENES.length-1?T('Nächste Situation','Next situation','Situation suivante'):T('Zur ersten Situation','Return to the first situation','Revenir à la première situation'))}</button></div>`:''}</div></section>`}
function bindLab(){const update=(selector)=>{pairRevealed=false;render(false);document.querySelector(selector)?.focus({preventScroll:true})};$('#dish-select')?.addEventListener('change',e=>{pairDish=+e.target.value;pairVariant=0;update('#dish-select')});$('#variant-select')?.addEventListener('change',e=>{pairVariant=+e.target.value;update('#variant-select')});$('#drink-select')?.addEventListener('change',e=>{pairDrink=+e.target.value;update('#drink-select')});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{pairMode=b.dataset.mode;pairDrink=0;update(`[data-mode="${pairMode}"]`)});$('#compare')?.addEventListener('click',()=>{pairRevealed=true;render(false);$('#compare').focus({preventScroll:true})});document.querySelectorAll('[data-aroma]').forEach(b=>b.onclick=()=>{aromaIndex=+b.dataset.aroma;render(false);document.querySelector(`[data-aroma="${aromaIndex}"]`).focus({preventScroll:true})});document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{currentScene=+b.dataset.scene;render(false);document.querySelector(`[data-scene="${currentScene}"]`)?.focus({preventScroll:true})});document.querySelectorAll('[data-scene-answer]').forEach(b=>b.onclick=()=>{sceneAnswers[currentScene]=+b.dataset.sceneAnswer;render(false);document.querySelector(`[data-scene-answer="${b.dataset.sceneAnswer}"]`).focus({preventScroll:true})});$('#next-scene')?.addEventListener('click',()=>{currentScene=(currentScene+1)%SCENES.length;render(false);$('.scene').scrollIntoView({behavior:'smooth',block:'start'})})}
render(false);
